ALTER TABLE daily_finance_accounts ALTER COLUMN finance_date DROP NOT NULL;
CREATE TABLE IF NOT EXISTS daily_finance_historical_collections (historical_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), customer_id UUID NOT NULL REFERENCES daily_finance_customers(customer_id), finance_id UUID NOT NULL REFERENCES daily_finance_accounts(finance_id), period_label VARCHAR(40) NOT NULL, amount NUMERIC(14,2) NOT NULL CHECK(amount>=0), source VARCHAR(120) NOT NULL DEFAULT 'Sheet1', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_df_historical_finance ON daily_finance_historical_collections(finance_id);
